113	// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
114	func (c *CodexAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
115		if path == "" {
116			return nil, 0, nil
117		}
118	
119		file, openErr := os.Open(path) //nolint:gosec // Path comes from agent hook input
120		if openErr != nil {
121			return nil, 0, fmt.Errorf("failed to open transcript: %w", openErr)
122		}
123		defer file.Close()
124	
125		reader := bufio.NewReader(file)
126		seen := make(map[string]struct{})
127		lineNum := 0
128	
129		for {
130			lineData, readErr := reader.ReadBytes('\n')
131			if readErr != nil && readErr != io.EOF {
132				return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
133			}
134	
135			if len(lineData) > 0 {
136				lineNum++
137				if lineNum > startOffset {
138					for _, f := range extractFilesFromLine(lineData) {
139						if _, ok := seen[f]; !ok {
140							seen[f] = struct{}{}
141							files = append(files, f)
142						}
143					}
144				}
145			}
146	
147			if readErr == io.EOF {
148				break
149			}
150		}
151	
152		return files, lineNum, nil
153	}
