180	// Format: "*** Add File: <path>" or "*** Update File: <path>" or "*** Delete File: <path>"
181	func extractFilesFromApplyPatch(input string) []string {
182		matches := applyPatchFileRegex.FindAllStringSubmatch(input, -1)
183		var files []string
184		seen := make(map[string]struct{})
185		for _, m := range matches {
