1	//! Hook-facing tool names and matcher compatibility aliases.
2	//!
3	//! Hook stdin exposes one canonical `tool_name`, but matcher selection may also
4	//! need to recognize names from adjacent tool ecosystems. Keeping those two
5	//! concepts together prevents handlers from accidentally serializing a
6	//! compatibility alias, such as `Write`, as the stable hook payload name.
7	
8	/// Identifies a tool in hook payloads and hook matcher selection.
9	///
10	/// `name` is the canonical value serialized into hook stdin. Matcher aliases are
11	/// internal-only compatibility names that may select the same hook handlers but
12	/// must not change the payload seen by hook processes.
13	#[derive(Clone, Debug, PartialEq, Eq)]
14	pub(crate) struct HookToolName {
15	    name: String,
16	    matcher_aliases: Vec<String>,
17	}
18	
19	impl HookToolName {
20	    /// Builds a hook tool name with no matcher aliases.
21	    pub(crate) fn new(name: impl Into<String>) -> Self {
22	        Self {
23	            name: name.into(),
24	            matcher_aliases: Vec::new(),
25	        }
26	    }
27	
28	    /// Returns the hook identity for file edits performed through `apply_patch`.
29	    ///
30	    /// The serialized name remains `apply_patch` so logs and policies can key
31	    /// off the actual Codex tool. `Write` and `Edit` are accepted as matcher
32	    /// aliases for compatibility with hook configurations that describe edits
33	    /// using Claude Code-style names.
34	    pub(crate) fn apply_patch() -> Self {
35	        Self {
36	            name: "apply_patch".to_string(),
37	            matcher_aliases: vec!["Write".to_string(), "Edit".to_string()],
38	        }
39	    }
40	
41	    /// Returns the hook identity historically used for shell-like tools.
42	    pub(crate) fn bash() -> Self {
43	        Self::new("Bash")
44	    }
45	
46	    /// Returns the canonical hook name serialized into hook stdin.
47	    pub(crate) fn name(&self) -> &str {
48	        &self.name
49	    }
50	
51	    /// Returns additional matcher inputs that should select the same handlers.
52	    pub(crate) fn matcher_aliases(&self) -> &[String] {
53	        &self.matcher_aliases
54	    }
55	}
