20	// Session state management functions shared across all strategies.
21	// SessionState is stored in .git/entire-sessions/{session_id}.json
22	
23	// getSessionStateDir returns the path to the session state directory.
24	// This is stored in the git common dir so it's shared across all worktrees.
25	func getSessionStateDir(ctx context.Context) (string, error) {
26		commonDir, err := GetGitCommonDir(ctx)
27		if err != nil {
28			return "", err
29		}
30		return filepath.Join(commonDir, session.SessionStateDirName), nil
31	}
