33	// sessionStateFile returns the path to a session state file.
34	func sessionStateFile(ctx context.Context, sessionID string) (string, error) {
35		stateDir, err := getSessionStateDir(ctx)
36		if err != nil {
37			return "", err
38		}
39		return filepath.Join(stateDir, sessionID+".json"), nil
40	}
