42	// LoadSessionState loads the session state for the given session ID.
43	// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
44	// Stale sessions are automatically deleted by the underlying StateStore.
45	func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
46		store, err := session.NewStateStore(ctx)
47		if err != nil {
48			return nil, fmt.Errorf("failed to create state store: %w", err)
49		}
50	
51		state, err := store.Load(ctx, sessionID)
52		if err != nil {
53			return nil, fmt.Errorf("failed to load session state: %w", err)
54		}
55		return state, nil
56	}
