58	// SaveSessionState saves the session state atomically.
59	func SaveSessionState(ctx context.Context, state *SessionState) error {
60		store, err := session.NewStateStore(ctx)
61		if err != nil {
62			return fmt.Errorf("failed to create state store: %w", err)
63		}
64	
65		if err := store.Save(ctx, state); err != nil {
66			return fmt.Errorf("failed to save session state: %w", err)
67		}
68		return nil
69	}
