71	// ListSessionStates returns all session states from the state directory.
72	// This is a package-level function that doesn't require a specific strategy instance.
73	func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
74		store, err := session.NewStateStore(ctx)
75		if err != nil {
76			return nil, fmt.Errorf("failed to create state store: %w", err)
77		}
78	
79		states, err := store.List(ctx)
80		if err != nil {
81			return nil, fmt.Errorf("failed to list session states: %w", err)
82		}
83		return states, nil
84	}
