86	// FindMostRecentSession returns the session ID of the most recently interacted session
87	// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
88	// Scoping to the current worktree prevents cross-worktree pollution in log routing.
89	// Falls back to unfiltered search if the worktree path can't be determined.
90	func FindMostRecentSession(ctx context.Context) string {
91		states, err := ListSessionStates(ctx)
92		if err != nil || len(states) == 0 {
93			return ""
94		}
95	
96		// Scope to current worktree to prevent cross-worktree pollution.
97		worktreePath, wpErr := paths.WorktreeRoot(ctx)
98		if wpErr == nil && worktreePath != "" {
99			var filtered []*SessionState
100			for _, s := range states {
101				if s.WorktreePath == worktreePath {
102					filtered = append(filtered, s)
103				}
104			}
105			if len(filtered) > 0 {
106				states = filtered
107			}
108			// If no sessions match the worktree, fall back to all sessions
109		}
110	
111		var best *SessionState
112		for _, s := range states {
113			if s.LastInteractionTime == nil {
114				continue
115			}
116			if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
117				best = s
118			}
119		}
120		if best != nil {
121			return best.SessionID
122		}
123	
124		// Fallback: return most recently started session
125		for _, s := range states {
126			if best == nil || s.StartedAt.After(best.StartedAt) {
127				best = s
128			}
129		}
130		if best != nil {
131			return best.SessionID
132		}
133		return ""
134	}
