136	// TransitionAndLog runs a session phase transition, applies actions via the
137	// handler, and logs the transition. Returns the first handler error from
138	// ApplyTransition (if any) so callers can surface it. The error is also
139	// logged internally for diagnostics.
140	// This is the single entry point for all state machine transitions to ensure
141	// consistent logging of phase changes.
142	func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
143		oldPhase := state.Phase
144		result := session.Transition(oldPhase, event, ctx)
145		logCtx := logging.WithComponent(goCtx, "session")
146	
147		handlerErr := session.ApplyTransition(goCtx, state, result, handler)
148		if handlerErr != nil {
149			logging.Error(logCtx, "action handler error during transition",
150				slog.String("session_id", state.SessionID),
151				slog.String("event", event.String()),
152				slog.Any("error", handlerErr),
153			)
154		}
155	
156		if result.NewPhase != oldPhase {
157			logging.Info(logCtx, "phase transition",
158				slog.String("session_id", state.SessionID),
159				slog.String("event", event.String()),
160				slog.String("from", string(oldPhase)),
161				slog.String("to", string(result.NewPhase)),
162			)
163		} else {
164			logging.Debug(logCtx, "phase unchanged",
165				slog.String("session_id", state.SessionID),
166				slog.String("event", event.String()),
167				slog.String("phase", string(result.NewPhase)),
168				slog.Any("result", result),
169			)
170		}
171	
172		if handlerErr != nil {
173			return fmt.Errorf("transition %s: %w", event, handlerErr)
174		}
175		return nil
176	}
