178	// StoreModelHint writes the LLM model name to a lightweight hint file
179	// (.git/entire-sessions/{session_id}.model) for cross-process persistence.
180	//
181	// Why a separate file instead of SessionState?
182	//
183	// SessionState requires BaseCommit (used for shadow branch naming, checkpoint
184	// writing, doctor classification, etc.) and is only created during TurnStart
185	// when the git repo is fully inspected. Some agents report the model on earlier
186	// hooks that fire as separate CLI processes before TurnStart:
187	//
188	//   - Claude Code sends "model" on SessionStart (before any TurnStart)
189	//   - Gemini CLI sends "llm_request.model" on BeforeModel (after TurnStart,
190	//     so handleLifecycleModelUpdate writes to SessionState directly when it
191	//     exists and only falls back to this hint file otherwise)
192	//
193	// The hint is read by handleLifecycleTurnStart/TurnEnd when event.Model is
194	// empty, passed to InitializeSession, and persisted in state.ModelName. After
195	// that the hint file is redundant — it sits unused until ClearSessionState
196	// removes it alongside the session state file.
197	func StoreModelHint(ctx context.Context, sessionID, model string) error {
198		if err := validation.ValidateSessionID(sessionID); err != nil {
199			return fmt.Errorf("invalid session ID: %w", err)
200		}
201		if model == "" {
202			return nil
203		}
204	
205		stateDir, err := getSessionStateDir(ctx)
206		if err != nil {
207			return fmt.Errorf("failed to get session state directory: %w", err)
208		}
209		if err := os.MkdirAll(stateDir, 0o750); err != nil {
210			return fmt.Errorf("failed to create session state directory: %w", err)
211		}
212	
213		hintFile := filepath.Join(stateDir, sessionID+".model")
214		if err := os.WriteFile(hintFile, []byte(model), 0o600); err != nil {
215			return fmt.Errorf("failed to write model hint file: %w", err)
216		}
217		return nil
218	}
219	
220	// LoadModelHint reads the LLM model name from the hint file for the given session.
221	// Returns empty string if the hint file doesn't exist or can't be read.
222	func LoadModelHint(ctx context.Context, sessionID string) string {
223		if err := validation.ValidateSessionID(sessionID); err != nil {
224			return ""
225		}
226	
227		stateDir, err := getSessionStateDir(ctx)
228		if err != nil {
229			logging.Warn(logging.WithComponent(ctx, "session"), "failed to resolve state dir for model hint",
230				slog.String("session_id", sessionID),
231				slog.Any("error", err))
232			return ""
233		}
234	
235		hintPath := filepath.Join(stateDir, sessionID+".model")
236		data, err := os.ReadFile(hintPath) //nolint:gosec // sessionID is validated above
237		if err != nil {
238			if !os.IsNotExist(err) {
239				logging.Warn(logging.WithComponent(ctx, "session"), "failed to read model hint file",
240					slog.String("path", hintPath),
241					slog.Any("error", err))
242			}
243			return ""
244		}
245		return strings.TrimSpace(string(data))
246	}
247	
248	// StoreAgentTypeHint records the agent type that owns a session before
249	// SessionState exists. Used by the lifecycle dispatcher when SessionStart fires
250	// (state isn't created until TurnStart, so we need a place to remember which
251	// agent claimed the session first).
252	//
253	// Semantics: first writer wins. When multiple agents fire hooks for the same
254	// session ID — e.g., Cursor IDE running cursor-agent while also forwarding to
255	// Claude Code's hook system — only the agent that fires SessionStart first
256	// gets recorded. Subsequent calls return nil without overwriting.
257	//
258	// At TurnStart, InitializeSession reads this hint to override agentType when
259	// the hook firing isn't the same agent that owns the session. After the state
260	// file is written, the hint is unused but remains until ClearSessionState
261	// removes it alongside the state file.
262	//
263	// Returns (created=true) when this call wrote the hint, (created=false) when
264	// the hint already existed (no-op) or agentType was empty/Unknown.
265	//
266	// Banner display is gated separately via ClaimSessionStartBanner — winning
267	// the ownership claim does NOT mean this agent should also print the banner,
268	// because the winner may not implement HookResponseWriter (e.g., Cursor).
269	func StoreAgentTypeHint(ctx context.Context, sessionID string, agentType types.AgentType) (created bool, err error) {
270		if vErr := validation.ValidateSessionID(sessionID); vErr != nil {
271			return false, fmt.Errorf("invalid session ID: %w", vErr)
272		}
273		if agentType == "" || agentType == agent.AgentTypeUnknown {
274			return false, nil
275		}
276	
277		stateDir, sErr := getSessionStateDir(ctx)
278		if sErr != nil {
279			return false, fmt.Errorf("failed to get session state directory: %w", sErr)
280		}
281		if mErr := os.MkdirAll(stateDir, 0o750); mErr != nil {
282			return false, fmt.Errorf("failed to create session state directory: %w", mErr)
283		}
284	
285		hintFile := filepath.Join(stateDir, sessionID+".agent")
286		f, oErr := os.OpenFile(hintFile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) //nolint:gosec // hintFile path is built from validated sessionID
287		if oErr != nil {
288			if errors.Is(oErr, os.ErrExist) {
289				// First-writer-wins: another caller already claimed this session.
290				return false, nil
291			}
292			return false, fmt.Errorf("failed to create agent hint file: %w", oErr)
293		}
294		defer f.Close()
295		if _, wErr := f.WriteString(string(agentType)); wErr != nil {
296			return false, fmt.Errorf("failed to write agent hint file: %w", wErr)
297		}
298		return true, nil
299	}
300	
301	// ClaimSessionStartBanner records that the SessionStart banner has been emitted
302	// for a session. First-writer-wins semantics, separate from StoreAgentTypeHint
303	// so a non-banner-capable agent winning the ownership race (e.g. Cursor, which
304	// doesn't implement HookResponseWriter) doesn't suppress the banner from a
305	// banner-capable agent that fires SessionStart for the same session.
306	//
307	// Callers MUST only invoke this from within the HookResponseWriter branch — the
308	// claim represents "a banner was actually shown", not just "an agent considered
309	// showing one". Otherwise a non-writer claimant would re-introduce the bug.
310	//
311	// Returns (claimed=true) when this call won the race and the caller should
312	// emit the banner; (claimed=false) when an earlier call already claimed it.
313	func ClaimSessionStartBanner(ctx context.Context, sessionID string) (claimed bool, err error) {
314		if vErr := validation.ValidateSessionID(sessionID); vErr != nil {
315			return false, fmt.Errorf("invalid session ID: %w", vErr)
316		}
317	
318		stateDir, sErr := getSessionStateDir(ctx)
319		if sErr != nil {
320			return false, fmt.Errorf("failed to get session state directory: %w", sErr)
321		}
322		if mErr := os.MkdirAll(stateDir, 0o750); mErr != nil {
323			return false, fmt.Errorf("failed to create session state directory: %w", mErr)
324		}
325	
326		markerFile := filepath.Join(stateDir, sessionID+".banner")
327		f, oErr := os.OpenFile(markerFile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) //nolint:gosec // markerFile path is built from validated sessionID
328		if oErr != nil {
329			if errors.Is(oErr, os.ErrExist) {
330				return false, nil
331			}
332			return false, fmt.Errorf("failed to create banner marker file: %w", oErr)
333		}
334		_ = f.Close()
335		return true, nil
336	}
337	
338	// LoadAgentTypeHint reads the agent type hint written by SessionStart.
339	// Returns empty string if the hint file doesn't exist, can't be read, or the
340	// value isn't a registered agent type.
341	func LoadAgentTypeHint(ctx context.Context, sessionID string) types.AgentType {
342		if err := validation.ValidateSessionID(sessionID); err != nil {
343			return ""
344		}
345	
346		stateDir, err := getSessionStateDir(ctx)
347		if err != nil {
348			logging.Warn(logging.WithComponent(ctx, "session"), "failed to resolve state dir for agent hint",
349				slog.String("session_id", sessionID),
350				slog.Any("error", err))
351			return ""
352		}
353	
354		hintPath := filepath.Join(stateDir, sessionID+".agent")
355		data, err := os.ReadFile(hintPath) //nolint:gosec // sessionID is validated above
356		if err != nil {
357			if !os.IsNotExist(err) {
358				logging.Warn(logging.WithComponent(ctx, "session"), "failed to read agent hint file",
359					slog.String("path", hintPath),
360					slog.Any("error", err))
361			}
362			return ""
363		}
364		return types.AgentType(strings.TrimSpace(string(data)))
365	}
366	
367	// ClearSessionState removes the session state file for the given session ID.
368	func ClearSessionState(ctx context.Context, sessionID string) error {
369		// Validate session ID to prevent path traversal
370		if err := validation.ValidateSessionID(sessionID); err != nil {
371			return fmt.Errorf("invalid session ID: %w", err)
372		}
373	
374		stateDir, err := getSessionStateDir(ctx)
375		if err != nil {
376			return fmt.Errorf("failed to get session state directory: %w", err)
377		}
378	
379		// Remove all files for this session (state .json, .model hint, any future hint files).
380		matches, _ := filepath.Glob(filepath.Join(stateDir, sessionID+".*")) //nolint:errcheck // pattern is always valid
381		for _, f := range matches {
382			_ = os.Remove(f)
383		}
384	
385		return nil
386	}
