// MutateSessionState is the safe load → mutate → save helper. It acquires an
// OS-level advisory lock against .git/entire-sessions/<id>.lock for the
// duration of the read+write so concurrent processes cannot lose each
// other's updates. fn receives the freshly-loaded state and mutates it in
// place; returning ErrMutationSkip skips the save. fn must be cheap — the
// lock is held for its full duration.
//
// Returns nil if the state file doesn't exist (the event arrived before
// InitializeSession). Errors from fn or from load/save propagate.
//
// All session-state mutations should funnel through this helper so the
// hot-path PostToolUse hook cannot revert fields written by lifecycle
// handlers (TurnEnd, PostCommit, ModelUpdate) that ran between our load
// and our save.
func MutateSessionState(ctx context.Context, sessionID string, fn func(*SessionState) error) error {
	if sessionID == "" {
		return nil
	}
	lockPath, err := stateLockPath(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("resolve state lock path: %w", err)
	}
	release, err := acquireStateFileLock(lockPath)
	if err != nil {
		return fmt.Errorf("acquire state lock: %w", err)
	}
	defer release()

	state, err := LoadSessionState(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("load session state: %w", err)
	}
	if state == nil {
		return nil
	}
	if err := fn(state); err != nil {
		if errors.Is(err, ErrMutationSkip) {
			return nil
		}
		return err
	}
	if err := SaveSessionState(ctx, state); err != nil {
		return fmt.Errorf("save session state: %w", err)
	}
	return nil
}

