// sessionMutationGate provides reentrant per-process mutual exclusion layered
// over the OS-level flock. POSIX flock isn't reentrant across distinct file
// descriptors in the same process — so if MutateSessionState was called
// recursively (one mutation handler calling another for the same session),
// the inner call would deadlock waiting for the outer flock. The sync.Mutex
// per session ID + ownership tracking lets nested calls skip the flock
// re-acquire safely while still fully serializing across processes.
var sessionMutationGate sync.Map // map[string]*sessionGate

type sessionGate struct {
	mu       sync.Mutex
	owner    int64 // goroutine ID of the holder, 0 when unlocked
	depth    int
	flockRel func()
}

