// acquireSessionGate takes the per-process gate (in-memory mutex) and the
// cross-process flock for the given session. The returned release decrements
// the gate; the flock is dropped only on the outermost release.
func acquireSessionGate(ctx context.Context, sessionID string) (func(), error) {
	val, _ := sessionMutationGate.LoadOrStore(sessionID, &sessionGate{})
	gate := val.(*sessionGate)

	gid := goroutineID()
	gate.mu.Lock()
	if gate.owner == gid {
		gate.depth++
		gate.mu.Unlock()
		return func() {
			gate.mu.Lock()
			gate.depth--
			gate.mu.Unlock()
		}, nil
	}
	gate.mu.Unlock()

	lockPath, err := stateLockPath(ctx, sessionID)
	if err != nil {
		return nil, fmt.Errorf("resolve state lock path: %w", err)
	}
	flockRel, err := acquireStateFileLock(lockPath)
	if err != nil {
		return nil, fmt.Errorf("acquire state lock: %w", err)
	}

	gate.mu.Lock()
	gate.owner = gid
	gate.depth = 1
	gate.flockRel = flockRel
	gate.mu.Unlock()

	return func() {
		gate.mu.Lock()
		gate.depth--
		if gate.depth == 0 {
			rel := gate.flockRel
			gate.flockRel = nil
			gate.owner = 0
			gate.mu.Unlock()
			rel()
			return
		}
		gate.mu.Unlock()
	}, nil
