			slog.Int("new_files", len(step.NewFiles)),
			slog.Int("deleted_files", len(step.DeletedFiles)),
			slog.String("shadow_branch", shadowBranchName),
			slog.Bool("branch_created", !branchExisted),
		)
		return nil
	})
